     2→import {GENESIS_SLOT} from "@lodestar/params";
     3→import {RespStatus, ResponseError, ResponseOutgoing} from "@lodestar/reqresp";
     4→import {computeEpochAtSlot} from "@lodestar/state-transition";
     5→import {ColumnIndex, fulu} from "@lodestar/types";
     6→import {fromHex} from "@lodestar/utils";
     7→import {IBeaconChain} from "../../../chain/index.js";
     8→import {IBeaconDb} from "../../../db/index.js";
     9→import {
    10→  handleColumnSidecarUnavailability,
    11→  validateRequestedDataColumns,
    12→} from "../utils/dataColumnResponseValidation.js";
    13→
    14→export async function* onDataColumnSidecarsByRange(
    15→  request: fulu.DataColumnSidecarsByRangeRequest,
    16→  chain: IBeaconChain,
    17→  db: IBeaconDb
    18→): AsyncIterable<ResponseOutgoing> {
    19→  // Non-finalized range of columns
    20→  const {startSlot, count, columns: requestedColumns} = validateDataColumnSidecarsByRangeRequest(chain.config, request);
    21→  const availableColumns = validateRequestedDataColumns(chain, requestedColumns);
    22→  const endSlot = startSlot + count;
    23→
    24→  if (availableColumns.length === 0) {
    25→    return;
    26→  }
    27→
    28→  const finalized = db.dataColumnSidecarArchive;
    29→  const unfinalized = db.dataColumnSidecar;
    30→  const finalizedSlot = chain.forkChoice.getFinalizedBlock().slot;
    31→
    32→  // Finalized range of columns
    33→  if (startSlot <= finalizedSlot) {
    34→    for (let slot = startSlot; slot < endSlot; slot++) {
    35→      const dataColumnSidecars = await finalized.getManyBinary(slot, availableColumns);
    36→
    37→      const unavailableColumnIndices: ColumnIndex[] = [];
    38→      for (let i = 0; i < dataColumnSidecars.length; i++) {
    39→        const dataColumnSidecarBytes = dataColumnSidecars[i];
    40→        if (dataColumnSidecarBytes) {
    41→          yield {
    42→            data: dataColumnSidecarBytes,
    43→            boundary: chain.config.getForkBoundaryAtEpoch(computeEpochAtSlot(slot)),
    44→          };
    45→        }
    46→
    47→        // TODO: Check blobs for that block and respond resource_unavailable
    48→        // After we have consensus from other teams on the specs
    49→        else {
    50→          unavailableColumnIndices.push(availableColumns[i]);
    51→        }
    52→      }
    53→
    54→      if (unavailableColumnIndices.length) {
    55→        await handleColumnSidecarUnavailability({
    56→          chain,
    57→          db,
    58→          metrics: chain.metrics,
    59→          unavailableColumnIndices,
    60→          slot,
    61→          requestedColumns,
    62→          availableColumns,
    63→        });
    64→      }
    65→    }
    66→  }
    67→
    68→  // Non-finalized range of columns
    69→  if (endSlot > finalizedSlot) {
    70→    const headRoot = chain.forkChoice.getHeadRoot();
    71→    const headChain = chain.forkChoice.getAllAncestorBlocks(headRoot);
    72→
    73→    // Iterate head chain with ascending block numbers
    74→    for (let i = headChain.length - 1; i >= 0; i--) {
    75→      const block = headChain[i];
    76→
    77→      // Must include only columns in the range requested
    78→      if (block.slot >= startSlot && block.slot < endSlot) {
    79→        // Note: Here the forkChoice head may change due to a re-org, so the headChain reflects the canonical chain
    80→        // at the time of the start of the request. Spec is clear the chain of columns must be consistent, but on
    81→        // re-org there's no need to abort the request
    82→        // Spec: https://github.com/ethereum/consensus-specs/blob/ad36024441cf910d428d03f87f331fbbd2b3e5f1/specs/fulu/p2p-interface.md#L425-L429
    83→        const dataColumnSidecars = await unfinalized.getManyBinary(fromHex(block.blockRoot), availableColumns);
    84→
    85→        const unavailableColumnIndices: ColumnIndex[] = [];
    86→        for (let i = 0; i < dataColumnSidecars.length; i++) {
    87→          const dataColumnSidecarBytes = dataColumnSidecars[i];
    88→          if (dataColumnSidecarBytes) {
    89→            yield {
    90→              data: dataColumnSidecarBytes,
    91→              boundary: chain.config.getForkBoundaryAtEpoch(computeEpochAtSlot(block.slot)),
    92→            };
    93→          }
    94→
    95→          // TODO: Check blobs for that block and respond resource_unavailable
    96→          // After we have consensus from other teams on the specs
    97→          else {
    98→            unavailableColumnIndices.push(availableColumns[i]);
    99→          }
   100→        }
   101→
   102→        if (unavailableColumnIndices.length) {
   103→          await handleColumnSidecarUnavailability({
   104→            chain,
   105→            db,
   106→            metrics: chain.metrics,
   107→            unavailableColumnIndices,
   108→            blockRoot: fromHex(block.blockRoot),
   109→            slot: block.slot,
   110→            requestedColumns,
   111→            availableColumns,
   112→          });
   113→        }
   114→      }
   115→
   116→      // If block is after endSlot, stop iterating
   117→      else if (block.slot >= endSlot) {
   118→        break;
   119→      }
   120→    }
   121→  }
   122→}
   123→
   124→export function validateDataColumnSidecarsByRangeRequest(
   125→  config: ChainConfig,
   126→  request: fulu.DataColumnSidecarsByRangeRequest
   127→): fulu.DataColumnSidecarsByRangeRequest {
   128→  const {startSlot, columns} = request;
   129→  let {count} = request;
